DECLARE @start_date date = '2022-01-01';
DECLARE @end_date date = '2024-02-29';

BEGIN TRY
    BEGIN TRANSACTION;

    IF OBJECT_ID('dbo.DimDate', 'U') IS NULL
    BEGIN
        CREATE TABLE dbo.DimDate (
            date_key int NOT NULL,
            calendar_date date NOT NULL,
            calendar_year int NOT NULL,
            calendar_quarter int NOT NULL,
            calendar_month int NOT NULL,
            day_of_month int NOT NULL,
            is_weekend bit NOT NULL
        );
    END;

    IF OBJECT_ID('dbo.DimZone', 'U') IS NULL
    BEGIN
        CREATE TABLE dbo.DimZone (
            location_id int NOT NULL,
            borough varchar(100) NULL,
            zone_name varchar(200) NULL,
            service_zone varchar(100) NULL
        );
    END;

    DELETE FROM dbo.DimDate;

    WITH calendar AS (
        SELECT DATEADD(day, [value], @start_date) AS calendar_date
        FROM GENERATE_SERIES(0, DATEDIFF(day, @start_date, @end_date), 1)
    )
    INSERT INTO dbo.DimDate (
        date_key, calendar_date, calendar_year, calendar_quarter,
        calendar_month, day_of_month, is_weekend
    )
    SELECT
        YEAR(calendar_date) * 10000 + MONTH(calendar_date) * 100 + DAY(calendar_date),
        calendar_date,
        YEAR(calendar_date),
        DATEPART(quarter, calendar_date),
        MONTH(calendar_date),
        DAY(calendar_date),
        CASE
            WHEN DATEDIFF(day, CAST('1900-01-01' AS date), calendar_date) % 7 IN (5, 6)
                THEN 1
            ELSE 0
        END
    FROM calendar;

    DELETE FROM dbo.DimZone;

    INSERT INTO dbo.DimZone (location_id, borough, zone_name, service_zone)
    SELECT location_id, borough, zone_name, service_zone
    FROM [lh_silver].[dbo].[taxi_zones];

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;

DECLARE @months_checked int;
DECLARE @months_with_differences int;
DECLARE @total_trips bigint;

WITH silver_monthly AS (
    SELECT
        YEAR(pickup_date) * 100 + MONTH(pickup_date) AS month_key,
        COUNT_BIG(*) AS trip_count,
        COUNT(DISTINCT pickup_date) AS days_loaded
    FROM [lh_silver].[dbo].[taxi_trips]
    WHERE is_outside_source_month = 0
    GROUP BY YEAR(pickup_date), MONTH(pickup_date)
),
gold_monthly AS (
    SELECT
        date_key / 100 AS month_key,
        SUM(trip_count) AS trip_count,
        COUNT(DISTINCT date_key) AS days_loaded
    FROM dbo.FactTaxiDaily
    GROUP BY date_key / 100
)
SELECT
    @months_checked = COUNT(*),
    @months_with_differences = COUNT(CASE
        WHEN s.month_key IS NULL OR g.month_key IS NULL
          OR s.trip_count <> g.trip_count
          OR s.days_loaded <> g.days_loaded
        THEN 1
    END),
    @total_trips = SUM(s.trip_count)
FROM silver_monthly AS s
FULL OUTER JOIN gold_monthly AS g
    ON s.month_key = g.month_key;

IF @months_checked = 0 OR @months_with_differences > 0
BEGIN
    THROW 50001, 'Taxi validation failed. Check Silver and Gold monthly counts.', 1;
END;

SELECT
    @months_checked AS months_checked,
    @months_with_differences AS months_with_differences,
    @total_trips AS total_trips;
